import{_ as i,o as e,c as a,a2 as l}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Lec.1 课程框架与 IC 设计全流程","description":"","frontmatter":{},"headers":[],"relativePath":"lectures/lec1.md","filePath":"lectures/lec1.md","lastUpdated":1782721500000}'),r={name:"lectures/lec1.md"};function o(n,t,c,s,d,u){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="lec-1-课程框架与-ic-设计全流程" tabindex="-1">Lec.1 课程框架与 IC 设计全流程 <a class="header-anchor" href="#lec-1-课程框架与-ic-设计全流程" aria-label="Permalink to &quot;Lec.1 课程框架与 IC 设计全流程&quot;">​</a></h1><blockquote><p><strong><em>Course Introduction</em></strong></p></blockquote><p>这讲的课件里有很多行政内容，比如 lecturer、assessment、course delivery、partner arrangement，这些不属于 DIC 知识点，笔记里不保留。真正有用的是：这门课把 Integrated Circuit 从 specification 到 layout、verification、cost review 的完整流程串起来。</p><h2 id="dic-这门课到底在学什么" tabindex="-1">DIC 这门课到底在学什么？ <a class="header-anchor" href="#dic-这门课到底在学什么" aria-label="Permalink to &quot;DIC 这门课到底在学什么？&quot;">​</a></h2><p>Design of Integrated Circuits 不是只画晶体管，也不是只跑仿真。它关心的是一个 IC 从需求到硅片实现的完整工程链条：</p><ol><li><strong>Specification / Requirements</strong>：把系统需求变成可以验证的设计指标。</li><li><strong>Architecture</strong>：把功能拆成 analog、digital、mixed-signal blocks。</li><li><strong>Circuit design</strong>：为每个 block 选择 topology，并估算器件尺寸、偏置、电压电流范围。</li><li><strong>Simulation</strong>：用 SPICE/VHDL 等工具验证电路行为、时序、corner、temperature 等。</li><li><strong>Layout</strong>：把 schematic 转成 silicon layout topology。</li><li><strong>Verification</strong>：做 DRC、LVS、back-annotation，确认版图可制造且等价于原电路。</li><li><strong>Review and cost</strong>：把 datasheet、key parameters、production cost 整理成 design review package。</li></ol><blockquote><p>可以把 DIC 理解成一句话：把一个功能需求变成可以制造、可以测试、可以解释成本的 chip design。</p></blockquote><h2 id="工具链-为什么课程用离散工具" tabindex="-1">工具链：为什么课程用离散工具？ <a class="header-anchor" href="#工具链-为什么课程用离散工具" aria-label="Permalink to &quot;工具链：为什么课程用离散工具？&quot;">​</a></h2><p>课程使用的是离散工具集，而不是一个完整工业 EDA flow。目的不是让工具“帮你自动完成”，而是让你看清每一步做了什么。</p><table tabindex="0"><thead><tr><th>Design step</th><th>Tool in course</th><th>作用</th></tr></thead><tbody><tr><td>Schematic entry</td><td>LTspice</td><td>画电路原理图</td></tr><tr><td>Circuit simulation</td><td>LTspice XVII</td><td>验证 analog circuit behavior</td></tr><tr><td>VHDL timing simulation</td><td>Xilinx Vivado</td><td>验证 digital timing / HDL behavior</td></tr><tr><td>Layout design</td><td>Electric VLSI</td><td>画 silicon layout</td></tr><tr><td>Layout verification</td><td>Electric VLSI</td><td>DRC / LVS</td></tr></tbody></table><p>这里的重点不是记软件名字，而是理解每个工具对应设计流程中的哪一层：</p><ul><li>schematic 是电路意图；</li><li>simulation 是行为验证；</li><li>layout 是物理实现；</li><li>DRC 是工艺规则检查；</li><li>LVS 是 layout 与 schematic 的一致性检查。</li></ul><h2 id="mixed-signal-ic-的工程视角" tabindex="-1">Mixed-Signal IC 的工程视角 <a class="header-anchor" href="#mixed-signal-ic-的工程视角" aria-label="Permalink to &quot;Mixed-Signal IC 的工程视角&quot;">​</a></h2><p>DIC 里的设计通常不是纯 analog 或纯 digital，而是 mixed-signal。一个 mixed-signal IC 往往同时需要：</p><ul><li>analog front-end，例如 amplifier、filter、bias、reference；</li><li>digital control，例如 state machine、counter、logic gate；</li><li>interface，例如 ADC、DAC、clock、I/O conditioning；</li><li>physical layout，例如 matching、routing、parasitics、guarding；</li><li>test plan，例如 DC/AC performance、functional verification、process/temperature coverage。</li></ul><p>这就是为什么后面的内容会同时出现 SPICE、VHDL、layout、analog blocks、digital blocks。</p><h2 id="本讲保留的知识点" tabindex="-1">本讲保留的知识点 <a class="header-anchor" href="#本讲保留的知识点" aria-label="Permalink to &quot;本讲保留的知识点&quot;">​</a></h2><ul><li>DIC 的目标是掌握 <strong>complete development process for an Integrated Circuit</strong>。</li><li>IC 设计不是单点技术，而是 requirements、architecture、circuit、simulation、layout、verification、review 的闭环。</li><li>课程中的 LTspice、Vivado、Electric VLSI 分别对应 analog simulation、digital simulation、layout/verification。</li><li>Assignment 中提到 datasheet、architecture、testing、layout、LVS、DRC，其实就是后续课程主线。</li></ul><h2 id="不作为知识点的内容" tabindex="-1">不作为知识点的内容 <a class="header-anchor" href="#不作为知识点的内容" aria-label="Permalink to &quot;不作为知识点的内容&quot;">​</a></h2><p>以下 PPT 内容不进入笔记正文：</p><ul><li>lecturer biography；</li><li>course assessment percentage；</li><li>group/partner organization；</li><li>late submission / resit policy；</li><li>reading list 的书目信息；</li><li>course delivery schedule。</li></ul><p>这些对完成课程有用，但不是 DIC 知识结构。</p>',22)])])}const h=i(r,[["render",o]]);export{p as __pageData,h as default};
